          kind: 'squash', value: lines.join('\n'), base: text(parents[0]),
          expect: text(commits[0].hash),
          hint: '将 ' + text(oldest.short) + '…' + text(newest.short) + ' 共 ' + String(count) + ' 个提交压缩为 1 个',
